import styled from 'styled-components';
import { FaGithub } from '@react-icons/all-files/fa/FaGithub';
import { FaYoutube } from '@react-icons/all-files/fa/FaYoutube';
import { FaInstagram } from '@react-icons/all-files/fa/FaInstagram';

const FooterContainer = styled.footer`
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  padding: 80px 424px 40px;
  background: linear-gradient(0deg, #010208 16.39%, #010206 20.51%, #040008 24.79%, #010101 30.46%, #010101 34.11%, #010101 36.21%, #010101 100%);

  @media (max-width: 768px) {
    padding: 80px 2rem 40px;
  }
`;

const Wrapper = styled.div`
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 80px;
  width: 100%;
  max-width: 592px;
`;

const Content = styled.div`
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 60px;
  width: 100%;
`;

const TitleSection = styled.div`
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 4px;
  width: 100%;
`;

const Title = styled.h2`
  font-family: 'Work Sans', sans-serif;
  font-weight: 300;
  font-size: 56px;
  line-height: 150%;
  text-align: center;
  letter-spacing: -0.02em;
  color: rgba(227, 228, 230, 0.55);
  margin: 0;

  @media (max-width: 768px) {
    font-size: 2.5rem;
  }
`;

const SubText = styled.p`
  font-family: 'Work Sans', sans-serif;
  font-weight: 300;
  font-size: 18px;
  line-height: 150%;
  text-align: center;
  color: #E3E4E6;
`;

const SocialIcons = styled.div`
  display: flex;
  flex-direction: row;
  justify-content: center;
  align-items: flex-start;
  gap: 56px;
  width: 100%;

  a {
    color: rgba(227, 228, 230, 0.55);
    font-size: 2rem;
    transition: color 0.3s;

    &:hover {
      color: #E3E4E6;
    }
  }
`;

const FooterNote = styled.p`
  font-family: 'Work Sans', sans-serif;
  font-weight: 300;
  font-size: 18px;
  line-height: 150%;
  text-align: center;
  color: rgba(227, 228, 230, 0.55);
  margin-top: 1rem;
`;

const ContactButton = styled.a`
  padding: 0.75rem 2rem;
  border: 2px solid #64ffda;
  color: #64ffda;
  font-weight: bold;
  border-radius: 5px;
  transition: 0.3s;
  text-decoration: none;
  margin-top: 2rem;

  &:hover {
    background: #64ffda;
    color: #0a192f;
  }
`;

const Footer = () => {
  return (
    <FooterContainer id="contact">
      <Wrapper>
        <Content>
          <TitleSection>
            <Title>Get in <span style={{ fontWeight: 'bold', color: '#ffffff' }}>Touch</span>.</Title>
            <SubText>Got an idea, project, or collaboration in mind? Let's talk and get it off the ground!</SubText>
          </TitleSection>
          <ContactButton href="mailto:jvcbatist4@outlook.com">Send e-mail</ContactButton>
          <SocialIcons>
            <a href="https://github.com/joaothedog" target="_blank" rel="noopener noreferrer"><FaGithub /></a>
            <a href="https://youtube.com/" target="_blank" rel="noopener noreferrer"><FaYoutube /></a>
            <a href="https://instagram.com/" target="_blank" rel="noopener noreferrer"><FaInstagram /></a>
          </SocialIcons>
        </Content>
        <FooterNote>© {new Date().getFullYear()} João Vitor. Developed w/ ❤️ and coffee.</FooterNote>
      </Wrapper>
    </FooterContainer>
  );
};

export default Footer;