import styled from 'styled-components';
import { motion } from 'framer-motion';
import { FaChevronDown } from '@react-icons/all-files/fa/FaChevronDown';
import { Link } from 'react-scroll';
import { FaPython } from '@react-icons/all-files/fa/FaPython';
import { FaReact } from '@react-icons/all-files/fa/FaReact';
import { FaVideo } from '@react-icons/all-files/fa/FaVideo';
import { FaCogs } from '@react-icons/all-files/fa/FaCogs';
import { SiTypescript } from '@react-icons/all-files/si/SiTypescript';
import { FaHtml5 } from '@react-icons/all-files/fa/FaHtml5';
import { FaCss3Alt } from '@react-icons/all-files/fa/FaCss3Alt';

const HeroSection = styled.section`
  min-height: 900px;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 0 112px;
  background: linear-gradient(180deg, #010208 16.39%, #010206 20.51%, #040008 24.79%, #010101 30.46%, #010101 34.11%, #010101 36.21%, #010101 100%);
  position: relative;

  @media (max-width: 768px) {
    padding: 0 1.5rem;
    text-align: center;
    min-height: 100vh;
  }
`;

const Content = styled.div`
  max-width: 1008px;
  text-align: center;
  padding-bottom: 80px;

  h1 {
    font-family: 'Work Sans', sans-serif;
    font-weight: 300;
    font-size: 56px;
    line-height: 150%;
    letter-spacing: -0.02em;
    color: rgba(227, 228, 230, 0.55);
    margin-bottom: 1rem;

    @media (max-width: 768px) {
      font-size: 2.2rem;
    }
  }

  p {
    font-family: 'Work Sans', sans-serif;
    font-weight: 300;
    font-size: 32px;
    line-height: 150%;
    color: rgba(227, 228, 230, 0.55);
    margin-bottom: 2rem;

    @media (max-width: 768px) {
      font-size: 1.2rem;
    }
  }

  button {
    margin-top: 2rem;
    padding: 12px 32px;
    background: transparent;
    border: 1px solid rgba(227, 228, 230, 0.55);
    border-radius: 100px;
    color: #E3E4E6;
    cursor: pointer;
    transition: all 0.3s;
    font-family: 'Work Sans', sans-serif;
    font-weight: 400;
    font-size: 16px;
    letter-spacing: 0.04em;
    text-transform: uppercase;
    position: relative;
    overflow: hidden;

    &::before {
      content: '';
      position: absolute;
      top: 0;
      left: -100%;
      width: 100%;
      height: 100%;
      background: linear-gradient(99.05deg, #BC3CD8 0.07%, #C54B8C 106.32%);
      transition: left 0.4s ease;
      z-index: -1;
    }

    &:hover {
      color: #ffffff;
      border-color: #C54B8C;

      &::before {
        left: 0;
      }
    }

    @media (max-width: 768px) {
      width: 100%;
      max-width: 300px;
    }
  }
`;

const ScrollIndicator = styled(motion.div)`
  position: absolute;
  bottom: 40px;
  left: 50%;
  transform: translateX(-50%);
  display: flex;
  flex-direction: column;
  align-items: center;
  cursor: pointer;
  z-index: 10;

  span {
    font-family: 'Work Sans', sans-serif;
    font-size: 12px;
    color: rgba(227, 228, 230, 0.7);
    margin-bottom: 8px;
    letter-spacing: 2px;
    text-transform: uppercase;
  }

  svg {
    color: rgba(227, 228, 230, 0.7);
    font-size: 1.8rem;
    transition: color 0.3s;
  }

  &:hover svg {
    color: #BC3CD8;
  }
`;

const TechStack = styled.div`
  display: flex;
  justify-content: center;
  gap: 24px;
  margin-top: 4rem;
  flex-wrap: wrap;

  @media (max-width: 768px) {
    gap: 16px;
  }
`;

const TechIcon = styled.div`
  display: flex;
  flex-direction: column;
  align-items: center;
  color: rgba(227, 228, 230, 0.55); /* Mesma cor do h1 */
  transition: all 0.3s ease;
  
  svg {
    font-size: 2rem;
    margin-bottom: 0.5rem;
    
    @media (max-width: 768px) {
      font-size: 1.5rem;
    }
  }

  span {
    font-family: 'Work Sans', sans-serif;
    font-size: 0.8rem;
    text-transform: uppercase;
    letter-spacing: 1px;
  }

  &:hover {
    color: #64ffda;
    transform: translateY(-5px);
  }
`;


const Hero = () => {
  return (
    <HeroSection id="hero">
      <Content as={motion.div} initial={{ opacity: 0, y: 40 }} animate={{ opacity: 1, y: 0 }} transition={{ duration: 1 }}>
        <h1>Hello, i am <span style={{ color: '#64ffda' }}>João Vitor</span></h1>
        <p>Web <span style={{ color: '#64ffda' }}>Developer</span> | Automation <span style={{ color: '#64ffda' }}>Specialist</span> | Video <span style={{ color: '#64ffda' }}>Editor</span></p>
        <p>I transform <span style={{ fontWeight: 'bold', color: '#ffffff' }}>ideas</span> into captivating interfaces, fluid experiences, and automated processes that save <span style={{ fontWeight: 'bold', color: '#ffffff' }}>time and energy</span>.</p>
        <button><Link to='projects' smooth duration={600}>Let's build something amazing?</Link></button>
        <TechStack>
          <TechIcon>
            <FaPython />
            <span>Python</span>
          </TechIcon>
          <TechIcon>
            <FaReact />
            <span>React</span>
          </TechIcon>
          <TechIcon>
            <SiTypescript />
            <span>TypeScript</span>
          </TechIcon>
          <TechIcon>
            <FaHtml5 />
            <span>HTML5</span>
          </TechIcon>
          <TechIcon>
            <FaCss3Alt />
            <span>CSS3</span>
          </TechIcon>
          <TechIcon>
            <FaVideo />
            <span>Video</span>
          </TechIcon>
          <TechIcon>
            <FaCogs />
            <span>Automation</span>
          </TechIcon>
        </TechStack>
      </Content>


      <Link to="about" smooth duration={600}>
        <ScrollIndicator
          initial={{ opacity: 0, y: 10 }}
          animate={{
            opacity: 1,
            y: 0,
            transition: {
              delay: 1.5,
              repeat: Infinity,
              repeatType: "reverse",
              duration: 1.5
            },
            marginBottom: '20px'
          }}
        >
          <span></span>
          <FaChevronDown />
        </ScrollIndicator>
      </Link>
    </HeroSection>
  );
};

export default Hero;