import { useRef, useEffect } from 'react';
import styled from 'styled-components';
import { motion } from 'framer-motion';
import { useInView } from 'react-intersection-observer';

// Importe seus vídeos
import videoHorizontal from '../assets/videos/video1.mp4';
import videoVertical1 from '../assets/videos/video3.mp4';
import videoVertical2 from '../assets/videos/video4.mp4';

const AboutSection = styled.section`
  display: flex;
  flex-direction: column;
  align-items: center;
  padding: 74px 107px;

  @media (max-width: 768px) {
    padding: 3rem 1.5rem;
  }
`;

const Wrapper = styled.div`
  display: flex;
  flex-direction: row;
  justify-content: center;
  align-items: center;
  gap: 34px;
  width: 100%;
  max-width: 1226px;

  @media (max-width: 768px) {
    flex-direction: column;
  }
`;

const TextContent = styled.div`
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 16px;
  flex: 1;

  @media (max-width: 768px) {
    align-items: center;
    text-align: center;
  }
`;

const Title = styled.h2`
  font-family: 'Work Sans', sans-serif;
  font-weight: 600;
  font-size: 24px;
  line-height: 150%;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: #E3E4E6;
`;

const Description = styled.p`
  font-family: 'Work Sans', sans-serif;
  text-align: justify;
  font-weight: 300;
  font-size: 28px;
  line-height: 150%;
  color: rgba(227, 228, 230, 0.55);

  @media (max-width: 768px) {
    font-size: 19px;
    text-align: center;
  }
`;

const MediaContainer = styled.div`
  display: flex;
  flex-direction: row;
  justify-content: flex-end;
  align-items: center;
  gap: 32px;
  flex: 1;

  @media (max-width: 768px) {
    flex-direction: column;
  }
`;

const Video = styled.video`
  border-radius: 16px;
  object-fit: cover;
  box-shadow: 0 4px 20px rgba(0, 0, 0, 0.25);
  background-color: #000;
`;

const HorizontalVideo = styled(Video)`
  width: 282px;
  height: 408px;

  @media (max-width: 480px) {
    width: 100%;
    height: 300px;
  }
`;

const VerticalVideos = styled.div`
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: flex-end;
  gap: 32px;
`;

const VerticalVideo = styled(Video)`
  width: 282px;
  height: 374px;

  &:last-child {
    height: 375px;
  }

  @media (max-width: 480px) {
    width: 100%;
    height: 250px;

    &:last-child {
      height: 250px;
    }
  }
`;

const About = () => {
  // Referências para os vídeos
  const horizontalVideoRef = useRef<HTMLVideoElement>(null);
  const verticalVideo1Ref = useRef<HTMLVideoElement>(null);
  const verticalVideo2Ref = useRef<HTMLVideoElement>(null);
  
  // Verifica se a seção está visível
  const { ref: sectionRef, inView } = useInView({
    threshold: 0.5, // Quando 50% da seção estiver visível
    triggerOnce: false
  });

  // Controla a reprodução dos vídeos
  useEffect(() => {
    if (inView) {
      horizontalVideoRef.current?.play();
      verticalVideo1Ref.current?.play();
      verticalVideo2Ref.current?.play();
    } else {
      horizontalVideoRef.current?.pause();
      verticalVideo1Ref.current?.pause();
      verticalVideo2Ref.current?.pause();
    }
  }, [inView]);

  return (
    <AboutSection id="about" ref={sectionRef}>
      <Wrapper>
        <TextContent as={motion.div} initial={{ opacity: 0, y: 40 }} whileInView={{ opacity: 1, y: 0 }} transition={{ duration: 0.6 }} viewport={{ once: true }}>
          <Title>About me</Title>
          <Description>
            I'm João Vitor, a <span style={{fontWeight: 'bold', color: '#ffffff'}}>technology enthusiast</span> specializing in <span style={{fontWeight: 'bold', color: '#ffffff'}}>web development, intelligent automation, and creative video editing</span> (both long and short).
          </Description>
        </TextContent>
        <MediaContainer>
          <HorizontalVideo
            ref={horizontalVideoRef}
            muted
            loop
            playsInline
            preload="auto"
          >
            <source src={videoHorizontal} type="video/mp4" />
            Your browser does not support the video tag.
          </HorizontalVideo>
          <VerticalVideos>
            <VerticalVideo
              ref={verticalVideo1Ref}
              muted
              loop
              playsInline
              preload="auto"
            >
              <source src={videoVertical1} type="video/mp4" />
              Your browser does not support the video tag.
            </VerticalVideo>
            <VerticalVideo
              ref={verticalVideo2Ref}
              muted
              loop
              playsInline
              preload="auto"
            >
              <source src={videoVertical2} type="video/mp4" />
              Your browser does not support the video tag.
            </VerticalVideo>
          </VerticalVideos>
        </MediaContainer>
      </Wrapper>
    </AboutSection>
  );
};

export default About;