import { createGlobalStyle } from 'styled-components';

export const GlobalStyle = createGlobalStyle`
  * {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
  }

  body {
    margin: 0;
    padding: 0;
    font-family: 'Work Sans', sans-serif;
    color: #E3E4E6;
    background: #010101;
  }

  a {
    text-decoration: none;
    color: inherit;
  }
`;